CREATE TABLE `business_custom_frames` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `custom_frame_purpose_id` bigint(20) unsigned NOT NULL,
  `custom_frame_image_type_id` bigint(20) unsigned NOT NULL,
  `original_zip_name` varchar(191) DEFAULT NULL,
  `zip_file_path` varchar(191) NOT NULL,
  `json_rules` longtext DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `show_on_landing` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  PRIMARY KEY (`id`),
  KEY `business_custom_frames_custom_frame_image_type_id_foreign` (`custom_frame_image_type_id`),
  KEY `idx_bcf_purpose_status` (`custom_frame_purpose_id`,`status`),
  CONSTRAINT `business_custom_frames_custom_frame_image_type_id_foreign` FOREIGN KEY (`custom_frame_image_type_id`) REFERENCES `custom_frame_image_types` (`id`) ON DELETE CASCADE,
  CONSTRAINT `business_custom_frames_custom_frame_purpose_id_foreign` FOREIGN KEY (`custom_frame_purpose_id`) REFERENCES `custom_frame_purposes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
