INSERT INTO `client_errors` VALUES (1,19,'ERR_FLUTTER','HttpException: Invalid statusCode: 403, uri = http://192.168.1.42/brandkit/uploads/http://192.168.1.42/brandkit/uploads/47e34519-b03a-46d4-aff4-bddb9e7be4f8.png','Android RMX3491_11_F.18','Pending','critical','Network Error','The app is creating a broken web link when trying to load an image. It\'s mistakenly adding the server address to a link that already has it, which confuses the server and causes an \'access denied\' error.','Review the code responsible for building image URLs, likely for the \'brandkit\' feature. Before prepending the base URL, add a check to see if the image path already starts with \'http://\' or \'https://\'. If it does, use the path as-is without modification to prevent creating a malformed URL.',100,1,'malformed_url_http_403','2026-06-02 11:17:40','2026-05-10 13:45:02','2026-06-02 11:17:40'),(2,18,'MANUAL_REPORT','User reporting a problem manually from My Business Support.','Web Browser','Pending',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,'2026-05-12 04:45:26','2026-05-12 04:45:26'),(3,18,'MANUAL_REPORT','User reporting a problem manually from Settings.','Web Browser','Pending','medium','UX Flow Issue','User ne Settings se problem report karne ki koshish ki, lekin koi detail nahi di. Isliye, humein pata nahi ki actual problem kya thi. Ho sakta hai ki report karne wala form ajeeb ho ya usme koi bug ho jiski vajah se user detail nahi de paaya.','1. Make the description field in the manual reporting form mandatory to prevent empty submissions. 2. Add clear placeholder text like \'Please describe the problem you are facing...\' to guide the user. 3. Enhance the feature to automatically attach basic logs and a screenshot of the last screen when a user initiates a manual report. This will provide context even if the user description is empty.',100,1,'manual_report_empty','2026-06-02 11:17:04','2026-05-15 14:26:20','2026-06-02 11:17:04'),(4,18,'MANUAL_REPORT','User reporting a problem manually from Settings.','Android RMX3491_11_F.18','Pending',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,'2026-07-07 06:46:34','2026-07-07 06:46:34');
/*!40000 ALTER TABLE `client_errors` ENABLE KEYS */;
UNLOCK TABLES;

