CREATE TABLE `editor_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `title` varchar(191) NOT NULL,
  `canvas_width` int(11) NOT NULL DEFAULT 1080,
  `canvas_height` int(11) NOT NULL DEFAULT 1080,
  `schema_json` longtext NOT NULL,
  `legacy_json` longtext DEFAULT NULL,
  `thumbnail_path` varchar(500) DEFAULT NULL,
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `author_id` bigint(20) unsigned DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `category` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `editor_templates_uuid_unique` (`uuid`),
  KEY `editor_templates_author_id_foreign` (`author_id`),
  CONSTRAINT `editor_templates_author_id_foreign` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
