INSERT INTO `mini_website_templates` VALUES (1,'Mini-Web1','7074baf2-7bb3-4278-9ed6-f0a156ee87e9.jpg','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>[[BUSINESS_NAME]]</title>\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css\">\r\n<style>\r\n*{margin:0;padding:0;box-sizing:border-box}\r\nbody{\r\nfont-family:\'Poppins\',sans-serif;\r\nbackground:#f3f3f3;\r\ndisplay:flex;\r\njustify-content:center;\r\npadding:20px;\r\n}\r\n.phone{\r\nwidth:100%;\r\nmax-width:480px;\r\nbackground:#fff;\r\nmin-height:100vh;\r\nborder-radius:28px;\r\noverflow:hidden;\r\nbox-shadow:0 20px 60px rgba(0,0,0,.15);\r\n}\r\n.header{\r\nheight:180px;\r\nbackground:\r\nlinear-gradient(135deg,#000 0%,#1a1a1a 100%);\r\nposition:relative;\r\n}\r\n.header:before{\r\ncontent:\'\';\r\nposition:absolute;\r\ninset:0;\r\nbackground:\r\nradial-gradient(circle at 20% 20%,rgba(255,255,255,.08) 0 40px,transparent 41px),\r\nradial-gradient(circle at 80% 40%,rgba(255,255,255,.06) 0 60px,transparent 61px);\r\n}\r\n.profile{\r\ntext-align:center;\r\nmargin-top:-65px;\r\npadding:0 20px;\r\nposition:relative;\r\nz-index:2;\r\n}\r\n.logo{\r\nwidth:130px;\r\nheight:130px;\r\nborder-radius:50%;\r\nbackground:#fff;\r\npadding:6px;\r\nbox-shadow:0 12px 30px rgba(0,0,0,.18);\r\nmargin:auto;\r\n}\r\n.logo img{\r\nwidth:100%;\r\nheight:100%;\r\nobject-fit:cover;\r\nborder-radius:50%;\r\n}\r\n.business-name{\r\nfont-size:28px;\r\nfont-weight:700;\r\ncolor:#000;\r\nmargin-top:18px;\r\nline-height:1.2;\r\n}\r\n.actions{\r\ndisplay:flex;\r\njustify-content:space-between;\r\ngap:12px;\r\npadding:25px 20px;\r\n}\r\n.action-btn{\r\nflex:1;\r\ntext-decoration:none;\r\ndisplay:flex;\r\nflex-direction:column;\r\nalign-items:center;\r\ngap:8px;\r\ncolor:#000;\r\n}\r\n.action-icon{\r\nwidth:58px;\r\nheight:58px;\r\nborder-radius:50%;\r\nbackground:#000;\r\ncolor:#fff;\r\ndisplay:flex;\r\nalign-items:center;\r\njustify-content:center;\r\nfont-size:22px;\r\ntransition:.3s;\r\n}\r\n.action-btn:hover .action-icon{\r\ntransform:translateY(-4px);\r\n}\r\n.contact-card{\r\nmargin:0 20px;\r\nbackground:#fff;\r\nborder:1px solid #eee;\r\nborder-radius:22px;\r\npadding:10px 0;\r\nbox-shadow:0 10px 25px rgba(0,0,0,.05);\r\n}\r\n.contact-item{\r\ndisplay:flex;\r\nalign-items:flex-start;\r\ngap:15px;\r\npadding:15px 20px;\r\nborder-bottom:1px solid #f1f1f1;\r\n}\r\n.contact-item:last-child{border-bottom:none}\r\n.contact-item i{\r\ncolor:#000;\r\nfont-size:18px;\r\nwidth:22px;\r\nmargin-top:3px;\r\n}\r\n.contact-item a,\r\n.contact-item span{\r\ncolor:#555;\r\ntext-decoration:none;\r\nword-break:break-word;\r\nfont-size:14px;\r\n}\r\n.social{\r\npadding:30px 20px;\r\ndisplay:flex;\r\njustify-content:center;\r\ngap:12px;\r\nflex-wrap:wrap;\r\n}\r\n.social a{\r\nwidth:50px;\r\nheight:50px;\r\nborder-radius:50%;\r\nborder:2px solid #000;\r\ncolor:#000;\r\ndisplay:flex;\r\nalign-items:center;\r\njustify-content:center;\r\nfont-size:20px;\r\ntext-decoration:none;\r\ntransition:.3s;\r\n}\r\n.social a:hover{\r\nbackground:#000;\r\ncolor:#fff;\r\n}\r\n.about{\r\npadding:0 20px 35px;\r\n}\r\n.section-title{\r\nfont-size:22px;\r\nfont-weight:700;\r\ncolor:#000;\r\nmargin-bottom:15px;\r\nposition:relative;\r\ndisplay:inline-block;\r\n}\r\n.section-title:after{\r\ncontent:\'\';\r\nposition:absolute;\r\nleft:0;\r\nbottom:-6px;\r\nwidth:60%;\r\nheight:3px;\r\nbackground:#000;\r\nborder-radius:5px;\r\n}\r\n.about-card{\r\nbackground:#fafafa;\r\nborder-radius:20px;\r\npadding:20px;\r\nborder:1px solid #eee;\r\n}\r\n.about-card h3{\r\nfont-size:18px;\r\ncolor:#000;\r\nmargin-bottom:12px;\r\n}\r\n.about-card p{\r\ncolor:#666;\r\nline-height:1.8;\r\nfont-size:14px;\r\n}\r\n.footer-space{\r\nheight:20px;\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"phone\">\r\n\r\n<div class=\"header\"></div>\r\n\r\n<div class=\"profile\">\r\n<div class=\"logo\">\r\n<img src=\"[[LOGO_URL]]\" alt=\"Logo\">\r\n</div>\r\n<div class=\"business-name\">[[BUSINESS_NAME]]</div>\r\n</div>\r\n\r\n<div class=\"actions\">\r\n<a href=\"tel:[[PHONE]]\" class=\"action-btn\">\r\n<div class=\"action-icon\"><i class=\"fa-solid fa-phone\"></i></div>\r\n<span>Call</span>\r\n</a>\r\n\r\n<a href=\"https://wa.me/[[PHONE]]\" class=\"action-btn\" target=\"_blank\">\r\n<div class=\"action-icon\"><i class=\"fa-brands fa-whatsapp\"></i></div>\r\n<span>WhatsApp</span>\r\n</a>\r\n\r\n<a href=\"#\" class=\"action-btn\">\r\n<div class=\"action-icon\"><i class=\"fa-solid fa-location-dot\"></i></div>\r\n<span>Location</span>\r\n</a>\r\n\r\n<a href=\"mailto:[[EMAIL]]\" class=\"action-btn\">\r\n<div class=\"action-icon\"><i class=\"fa-solid fa-envelope\"></i></div>\r\n<span>Email</span>\r\n</a>\r\n</div>\r\n\r\n<div class=\"contact-card\">\r\n\r\n<div class=\"contact-item\">\r\n<i class=\"fa-solid fa-location-dot\"></i>\r\n<span>[[ADDRESS]]</span>\r\n</div>\r\n\r\n<div class=\"contact-item\">\r\n<i class=\"fa-solid fa-envelope\"></i>\r\n<a href=\"mailto:[[EMAIL]]\">[[EMAIL]]</a>\r\n</div>\r\n\r\n<div class=\"contact-item\">\r\n<i class=\"fa-solid fa-globe\"></i>\r\n<a href=\"[[WEBSITE]]\" target=\"_blank\">[[WEBSITE]]</a>\r\n</div>\r\n\r\n<div class=\"contact-item\">\r\n<i class=\"fa-solid fa-phone\"></i>\r\n<a href=\"tel:[[PHONE]]\">[[PHONE]]</a>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"social\">\r\n<a href=\"[[FACEBOOK]]\" target=\"_blank\"><i class=\"fab fa-facebook-f\"></i></a>\r\n<a href=\"[[TWITTER]]\" target=\"_blank\"><i class=\"fab fa-x-twitter\"></i></a>\r\n<a href=\"[[INSTAGRAM]]\" target=\"_blank\"><i class=\"fab fa-instagram\"></i></a>\r\n<a href=\"[[YOUTUBE]]\" target=\"_blank\"><i class=\"fab fa-youtube\"></i></a>\r\n<a href=\"[[LINKEDIN]]\" target=\"_blank\"><i class=\"fab fa-linkedin-in\"></i></a>\r\n</div>\r\n\r\n<div class=\"about\">\r\n<div class=\"section-title\">ABOUT US</div>\r\n\r\n<div class=\"about-card\">\r\n<h3>Business Name : [[BUSINESS_NAME]]</h3>\r\n<p>[[ABOUT_US]]</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"footer-space\"></div>\r\n\r\n</div>\r\n\r\n<script>\r\ndocument.querySelectorAll(\'a[href=\"#\"]\').forEach(btn=>{\r\nbtn.addEventListener(\'click\',e=>{\r\ne.preventDefault();\r\n});\r\n});\r\n</script>\r\n</body>\r\n</html>',1,'2026-06-03 14:44:37','2026-06-13 12:46:54'),(2,'Mini-Web2','117c9d62-969f-41e6-8599-3fdb60769412.jpg','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>[[BUSINESS_NAME]]</title>\r\n\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css\">\r\n\r\n<style>\r\n:root{\r\n--primary:#6123be;\r\n--secondary:#4de42f;\r\n--bg:#050505;\r\n--card:#121212;\r\n--text:#ffffff;\r\n--muted:#b8b8b8;\r\n}\r\n\r\n*{\r\nmargin:0;\r\npadding:0;\r\nbox-sizing:border-box;\r\n}\r\n\r\nbody{\r\nfont-family:\'Poppins\',sans-serif;\r\nbackground:#000;\r\ncolor:#fff;\r\noverflow-x:hidden;\r\ndisplay:flex;\r\njustify-content:center;\r\npadding:15px;\r\n}\r\n\r\n.container{\r\nwidth:100%;\r\nmax-width:480px;\r\nbackground:var(--bg);\r\nborder-radius:28px;\r\noverflow:hidden;\r\nborder:1px solid rgba(255,255,255,.08);\r\nbox-shadow:0 20px 80px rgba(0,0,0,.7);\r\n}\r\n\r\n/* HERO */\r\n.hero{\r\nheight:190px;\r\n\r\nposition:relative;\r\noverflow:hidden;\r\n}\r\n\r\n.profile{\r\ntext-align:center;\r\npadding:0 20px 25px;\r\nmargin-top:-70px;\r\n}\r\n\r\n.logo{\r\nwidth:clamp(110px,28vw,150px);\r\nheight:clamp(110px,28vw,150px);\r\nmargin:auto;\r\nborder-radius:50%;\r\npadding:5px;\r\nbackground:linear-gradient(135deg,var(--secondary),#fff);\r\nbox-shadow:0 15px 40px rgba(0,0,0,.5);\r\n}\r\n\r\n.logo img{\r\nwidth:100%;\r\nheight:100%;\r\nobject-fit:cover;\r\nborder-radius:50%;\r\ndisplay:block;\r\n}\r\n\r\n.name{\r\nfont-size:clamp(24px,6vw,32px);\r\nfont-weight:800;\r\nmargin-top:15px;\r\nline-height:1.2;\r\nword-break:break-word;\r\n}\r\n\r\n.tag{\r\nfont-size:14px;\r\ncolor:var(--muted);\r\nmargin-top:5px;\r\n}\r\n\r\n/* ACTIONS */\r\n.quick{\r\ndisplay:grid;\r\ngrid-template-columns:repeat(4,1fr);\r\ngap:10px;\r\npadding:0 20px 25px;\r\n}\r\n\r\n.quick a{\r\ntext-decoration:none;\r\nbackground:var(--card);\r\nborder:1px solid rgba(255,255,255,.08);\r\nborder-radius:18px;\r\npadding:14px 5px;\r\ntext-align:center;\r\ncolor:#fff;\r\ntransition:.3s;\r\n}\r\n\r\n.quick a:hover{\r\ntransform:translateY(-3px);\r\nborder-color:var(--secondary);\r\n}\r\n\r\n.quick i{\r\ndisplay:block;\r\nfont-size:22px;\r\nmargin-bottom:8px;\r\ncolor:var(--secondary);\r\n}\r\n\r\n/* CONTACT */\r\n.section{\r\npadding:0 20px 22px;\r\n}\r\n\r\n.card{\r\nbackground:var(--card);\r\nborder-radius:20px;\r\npadding:18px;\r\nborder:1px solid rgba(255,255,255,.06);\r\n}\r\n\r\n.row{\r\ndisplay:flex;\r\ngap:12px;\r\npadding:12px 0;\r\nborder-bottom:1px solid rgba(255,255,255,.06);\r\n}\r\n\r\n.row:last-child{\r\nborder:none;\r\n}\r\n\r\n.row i{\r\nwidth:20px;\r\ncolor:var(--secondary);\r\nmargin-top:3px;\r\n}\r\n\r\n.row div{\r\nword-break:break-word;\r\noverflow-wrap:break-word;\r\nfont-size:14px;\r\n}\r\n\r\n/* STATS */\r\n.stats{\r\ndisplay:grid;\r\ngrid-template-columns:repeat(3,1fr);\r\ngap:10px;\r\npadding:0 20px 22px;\r\n}\r\n\r\n.stat{\r\nbackground:linear-gradient(145deg,#141414,#1b1b1b);\r\nborder-radius:18px;\r\npadding:18px 10px;\r\ntext-align:center;\r\nborder:1px solid rgba(255,255,255,.05);\r\noverflow:hidden;\r\n}\r\n\r\n.stat h3{\r\ncolor:var(--secondary);\r\nfont-size:clamp(14px, 4vw, 22px);\r\nfont-weight:700;\r\nword-break:break-word;\r\n}\r\n\r\n.stat p{\r\nfont-size:13px;\r\ncolor:#ccc;\r\n}\r\n\r\n/* SOCIAL */\r\n.social{\r\ndisplay:flex;\r\njustify-content:center;\r\ngap:12px;\r\npadding:0 20px 25px;\r\nflex-wrap:wrap;\r\n}\r\n\r\n.social a{\r\nwidth:50px;\r\nheight:50px;\r\nborder-radius:50%;\r\ndisplay:flex;\r\nalign-items:center;\r\njustify-content:center;\r\nbackground:var(--card);\r\nborder:1px solid rgba(255,255,255,.08);\r\ncolor:#fff;\r\ntext-decoration:none;\r\ntransition:.3s;\r\n}\r\n\r\n.social a:hover{\r\nbackground:var(--primary);\r\ntransform:translateY(-3px);\r\n}\r\n\r\n/* CONTENT */\r\n.title{\r\nfont-size:18px;\r\nfont-weight:700;\r\nmargin-bottom:12px;\r\ncolor:var(--secondary);\r\nletter-spacing:1px;\r\n}\r\n\r\n.content{\r\nbackground:var(--card);\r\npadding:20px;\r\nborder-radius:20px;\r\nline-height:1.8;\r\ncolor:#d8d8d8;\r\nborder:1px solid rgba(255,255,255,.06);\r\n}\r\n\r\n.footer{\r\npadding:20px;\r\ntext-align:center;\r\nfont-size:12px;\r\ncolor:#666;\r\n}\r\n\r\n/* RESPONSIVE */\r\n@media(max-width:420px){\r\n  .quick{\r\n    grid-template-columns:repeat(2,1fr);\r\n  }\r\n  .stats{\r\n    grid-template-columns:repeat(2,1fr);\r\n  }\r\n  .stats .stat:last-child{\r\n    grid-column:span 2;\r\n  }\r\n}\r\n</style>\r\n</head>\r\n\r\n<body>\r\n\r\n<div class=\"container\">\r\n\r\n<div class=\"hero\"></div>\r\n\r\n<div class=\"profile\">\r\n<div class=\"logo\">\r\n<img src=\"[[LOGO_URL]]\" alt=\"Logo\">\r\n</div>\r\n\r\n<div class=\"name\">[[BUSINESS_NAME]]</div>\r\n<div class=\"tag\">Professional Business Profile</div>\r\n</div>\r\n\r\n<div class=\"quick\">\r\n<a href=\"tel:[[PHONE]]\"><i class=\"fas fa-phone\"></i>Call</a>\r\n<a href=\"https://wa.me/[[WHATSAPP_NUMBER]]\"><i class=\"fab fa-whatsapp\"></i>WhatsApp</a>\r\n<a href=\"[[MAP_URL]]\"><i class=\"fas fa-location-dot\"></i>Location</a>\r\n<a href=\"mailto:[[EMAIL]]\"><i class=\"fas fa-envelope\"></i>Email</a>\r\n</div>\r\n\r\n<div class=\"section\">\r\n<div class=\"card\">\r\n\r\n<div class=\"row\">\r\n<i class=\"fas fa-location-dot\"></i>\r\n<div>[[ADDRESS]]</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<i class=\"fas fa-envelope\"></i>\r\n<div>[[EMAIL]]</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<i class=\"fas fa-globe\"></i>\r\n<div>[[WEBSITE]]</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<i class=\"fas fa-phone\"></i>\r\n<div>[[PHONE]]</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"stats\">\r\n<div class=\"stat\">\r\n<h3>[[CLIENTS_COUNT]]</h3>\r\n<p>Clients</p>\r\n</div>\r\n\r\n<div class=\"stat\">\r\n<h3>[[YEARS_EXPERIENCE]]</h3>\r\n<p>Experience</p>\r\n</div>\r\n\r\n<div class=\"stat\">\r\n<h3>24/7</h3>\r\n<p>Support</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"social\">\r\n<a href=\"[[FACEBOOK]]\"><i class=\"fab fa-facebook-f\"></i></a>\r\n<a href=\"[[TWITTER]]\"><i class=\"fab fa-x-twitter\"></i></a>\r\n<a href=\"[[INSTAGRAM]]\"><i class=\"fab fa-instagram\"></i></a>\r\n<a href=\"[[YOUTUBE]]\"><i class=\"fab fa-youtube\"></i></a>\r\n<a href=\"[[LINKEDIN]]\"><i class=\"fab fa-linkedin-in\"></i></a>\r\n</div>\r\n\r\n<div class=\"section\">\r\n<div class=\"title\">ABOUT US</div>\r\n<div class=\"content\">\r\n<b>Business Name :</b> [[BUSINESS_NAME]]<br><br>\r\n[[ABOUT_US]]\r\n</div>\r\n</div>\r\n\r\n<div class=\"section\">\r\n<div class=\"title\">OUR SERVICES</div>\r\n<div class=\"content\">\r\n[[PRODUCTS_SERVICES]]\r\n</div>\r\n</div>\r\n\r\n<div class=\"footer\">\r\nPowered by [[BUSINESS_NAME]]\r\n</div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>',1,'2026-06-13 13:10:58','2026-06-13 13:10:58');
