DROP TABLE IF EXISTS `tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tickets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `subject` varchar(191) NOT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'open' COMMENT 'open, in_progress, closed, ai_resolved',
  `sentiment` varchar(191) NOT NULL DEFAULT 'neutral',
  `priority` varchar(191) NOT NULL DEFAULT 'low' COMMENT 'low, medium, high, urgent',
  `category` varchar(191) NOT NULL DEFAULT 'general' COMMENT 'billing, technical, feature_request, general',
  `sentiment_score` double(8,2) DEFAULT NULL COMMENT '0 to 10 score assigned by AI',
  `ai_rating` int(11) DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tickets_user_id_foreign` (`user_id`),
  CONSTRAINT `tickets_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
